def top_k_frequent(nums, k):
    # Create a min heap
    heap = []
    for num in nums:
        if num not in heap:
            heap.append(num)
        else:
            heap.remove(num)
    # Sort the heap
    heap.sort()
    # Return the top k elements
    return heap[:k]

def max_Prime_Factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n = n // i
    if n > 2:
        factors.append(n)
    return max(factors)

