def longest_subseq_with_diff_one(arr, diff):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for i in range(n-1):
        for j in range(i+1, n):
            if arr[i] == arr[j] and abs(arr[i] - arr[j]) == diff:
                dp[i][j] = 2
            elif arr[i] == arr[j]:
                dp[i][j] = dp[i+1][j-1] + 1
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])
    return dp[0][-1]

