def max_sum(arr, k):
    n = len(arr)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        for j in range(k + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif arr[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - arr[i - 1]] + arr[i - 1])
    return dp[n][k]

def babylonian_squareroot(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a = 1
        b = n
        c = 0
        while c**2 > b:
            c = c + 1
        d = c**2
        e = b - d
        f = a + (e / c)
        return f

def lps(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 0
    for i in range(n-1):
        dp[i][i] = 1
    for i in range(n-1):
        for j in range(n-1):
            if s[i] == s[j] and i + j < n:
                dp[i][j] = dp[i+1][j+1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j+1])
    return dp[0][n-1]

